void sharpen3x3::thread_hdltv_gen() {
    const char* dump_tv = std::getenv("AP_WRITE_TV");
    if (!(dump_tv && string(dump_tv) == "on")) return;

    wait();

    mHdltvinHandle << "[ " << endl;
    mHdltvoutHandle << "[ " << endl;
    int ap_cycleNo = 0;
    while (1) {
        wait();
        const char* mComma = ap_cycleNo == 0 ? " " : ", " ;
        mHdltvinHandle << mComma << "{"  <<  " \"ap_rst\" :  \"" << ap_rst.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"ap_start\" :  \"" << ap_start.read() << "\" ";
        mHdltvoutHandle << mComma << "{"  <<  " \"ap_done\" :  \"" << ap_done.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_idle\" :  \"" << ap_idle.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_ready\" :  \"" << ap_ready.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"src_V_V_dout\" :  \"" << src_V_V_dout.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"src_V_V_empty_n\" :  \"" << src_V_V_empty_n.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"src_V_V_read\" :  \"" << src_V_V_read.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"dst_V_V_din\" :  \"" << dst_V_V_din.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"dst_V_V_full_n\" :  \"" << dst_V_V_full_n.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"dst_V_V_write\" :  \"" << dst_V_V_write.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"width_V\" :  \"" << width_V.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"height_V\" :  \"" << height_V.read() << "\" ";
        mHdltvinHandle << "}" << std::endl;
        mHdltvoutHandle << "}" << std::endl;
        ap_cycleNo++;
    }
}

